// Embeds the scenario into server modules so deployment bundles carry it
// without file tracing. Run after editing anything under scenarios/.
//   node scripts/build-eng-scenario.mjs          write
//   node scripts/build-eng-scenario.mjs --check  fail if generated files drift
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { SCENARIO_DIR, readTree, buildStarterZip, sha256 } from './eng-scenario-lib.mjs';

const OUT_DIR = path.join(process.cwd(), 'src', 'lib', 'eng', 'scenarios', 'backend-webhook-retry');
const check = process.argv.includes('--check');

const starter = await readTree(path.join(SCENARIO_DIR, 'starter'));
const harness = (await readFile(path.join(SCENARIO_DIR, 'evaluator', 'harness.py'), 'utf8')).replace(/\r\n/g, '\n');
const expectations = JSON.parse(await readFile(path.join(SCENARIO_DIR, 'evaluator', 'expectations.json'), 'utf8'));
const starterSha = sha256(buildStarterZip(starter));
const harnessSha = sha256(Buffer.from(harness));

const header = '// Generated by scripts/build-eng-scenario.mjs from scenarios/backend-webhook-retry. Do not edit.\n';
const starterModule = `${header}export const STARTER_FILES: Readonly<Record<string, string>> = ${JSON.stringify(starter, null, 2)};\n\nexport const STARTER_SHA256 = ${JSON.stringify(starterSha)};\n`;
const hiddenModule = `${header}import "server-only";\n\nexport const HARNESS_SOURCE = ${JSON.stringify(harness)};\n\nexport const HARNESS_SHA256 = ${JSON.stringify(harnessSha)};\n\nexport const EXPECTATIONS = ${JSON.stringify(expectations, null, 2)} as const;\n`;

const targets = [
  [path.join(OUT_DIR, 'starter.generated.ts'), starterModule],
  [path.join(OUT_DIR, 'hidden.generated.ts'), hiddenModule],
];

if (check) {
  let drift = false;
  for (const [file, content] of targets) {
    const current = await readFile(file, 'utf8').catch(() => '');
    if (current.replace(/\r\n/g, '\n') !== content) {
      console.error(`Out of date: ${path.relative(process.cwd(), file)}. Run node scripts/build-eng-scenario.mjs`);
      drift = true;
    }
  }
  process.exit(drift ? 1 : 0);
}

await mkdir(OUT_DIR, { recursive: true });
for (const [file, content] of targets) await writeFile(file, content);
console.log(`Starter archive sha256 ${starterSha} (${Object.keys(starter).length} files). Harness sha256 ${harnessSha}.`);
